method Initialize controller {
    $self reset $controller;       # Reset the device:
    if {[array names ::env MVLC_TRANSLATOR] eq ""} {;   # VMUSB
        while {([$controller vmeRead32 $resetreg $CVMUSBReadoutList::a32UserData] & 0x80000000) != 0x80000000} {

        }
    } else {;                       # mvlcgenerate
        $controller loopUntil32 $resetreg $CVMUSBReadoutList::a32UserData 0x80000000 0x80000000
    }
}

refsynopsisdiv.programlisting:
#include <mvlc/CReadoutHardware.h>
class CReadoutHardware {
public:
    CReadoutHardware();
    virtual ~CReadoutHardware();
    void setConfiguration(XXUSB::CConfigurableObject* pConfig);
    XXUSB::CConfigurableObject* getConfiguration() { return m_pConfiguration; }

    virtual void onAttach(XXUSB::CConfigurableObject& configuration);
    virtual void Initialize(CVMUSB& controller);
    virtual void addReadoutList(CVMUSBReadoutList& list);
    virtual void onEndRun(CVMUSB& controller);

 };

#include <mvlc/DeviceCommand.h>

class DeviceCommand : public CTCLObjectProcessor {

public:
    DeviceCommand(CTCLInterpreter& interp, const char* cmd, TCLConfigParser& parser);
    virtual ~DeviceCommand();
    virtual int operator()(CTCLInterpreter& interp, std::vector<CTCLObject>& objv);

protected:
    //
    virtual CReadoutModule* createDevice(std::string name) = 0; 
    TCLConfigParser& getParser() {return m_parser; }

};

#include <CReadoutModule.h>

class CReadoutModule {

public:

    CReadoutModule();
    virtual ~CReadoutModule();   // Not willing yet to declare this as final.

    CReadoutHardware* getDriver();
    XXUSB::CConfigurableObject* getConfiguration();
    void Attach(XXUSB::CConfigurableObject* config);
    void SetDriver(CReadoutHardware* pDriver);
    void Initialize(CVMUSB& controller);
    void addReadoutList(CVMUSBReadoutList& list);
    void onEndRun(CVMUSB& controller);

};

#include <CVMUSB.h>

class CVMUSB {
public:

    virtual int vmeWrite32(uint32_t address, uint8_t aModifier, uint32_t data);
    virtual int vmeWrite16(uint32_t address, uint8_t aModifier, uint16_t data);
    virtual int vmeBlockWrite32(uint32_t base, uint32_t aModifier, uint32_t* pData, size_t nTransfers);
    virtual void delay(uint32_t amount);
    virtual void loopUntil32(uint32_t address, uint8_t amod, uint32_t mask, uint32_t value);
    virtual void loopUntil16(uint32_t address, uint8_t amod, uint32_t mask, uint32_t value);

    std::vector<std::string> getRecordedOperations();
    void clearRecordedOperations();

    virtual int executeList(CVMUSBReadoutList& list, void* pReadBuffer, size_t readBufferSize, size_t* bytesRead);
    std::vector<uint8_t< executeList(CVMUSBReadoutList& list, int maxBytes);
};
